// Some portions generated by Co-Pilot
"use client";

import { useId, useState } from "react";
import Image from "next/image";
import { Link } from "@/i18n/navigation";
import { useTranslations, useLocale } from "next-intl";
import { BsCopy } from "react-icons/bs";
import { FiDownload, FiRotateCcw, FiSearch } from "react-icons/fi";
import ChecksumModal from "@/components/Download/ChecksumModal";
import type { MarketplaceRelease } from "@/hooks";
import { sendDownloadEvent } from "@/utils/gtag";
import { capitalize } from "@/utils/capitalize";
import { getImageForDistribution } from "@/hooks";
import { getExtension } from "@/utils/temurin";
import vendors from "@/data/marketplace.json";
import getVendorIdentifier from "@/utils/vendors";

type Binary = NonNullable<MarketplaceRelease["binary"]>;
type Package = NonNullable<Binary["package"]>;
type DownloadableRelease = MarketplaceRelease & {
  binary: Binary & { package: Package };
  vendor: NonNullable<MarketplaceRelease["vendor"]>;
};

interface AllReleaseCardProps {
  results: MarketplaceRelease[] | null;
  onReset?: () => void;
}

const AllReleaseCard = ({ results, onReset }: AllReleaseCardProps) => {
  const t = useTranslations();
  const locale = useLocale();
  const id = useId();
  const [modalOpen, setModalOpen] = useState(false);
  const [currentChecksum, setCurrentChecksum] = useState("");

  if (results === null) {
    return (
      <div
        role="status"
        aria-label={t("Marketplace.Releases.loading")}
        className="mt-8 grid gap-4 lg:grid-cols-2"
        data-testid="marketplace-loading"
      >
        {[1, 2, 3].map((index) => (
          <div
            key={index}
            className="rounded-2xl border border-white/10 bg-white/[0.025] p-6 motion-safe:animate-pulse"
          >
            <div className="mb-6 h-10 w-48 rounded bg-white/10" />
            <div className="mb-6 grid grid-cols-2 gap-4">
              <div className="h-12 rounded-lg bg-white/5" />
              <div className="h-12 rounded-lg bg-white/5" />
            </div>
            <div className="h-11 w-full rounded-lg bg-white/5" />
          </div>
        ))}
      </div>
    );
  }
  const releases = results.filter((release): release is DownloadableRelease =>
    Boolean(release.binary?.package?.link && release.vendor),
  );
  if (releases.length === 0) {
    return (
      <div
        role="status"
        className="mt-8 rounded-2xl border border-white/10 bg-white/[0.025] px-6 py-12 text-center"
      >
        <FiSearch
          className="mx-auto mb-4 text-grey"
          size={32}
          aria-hidden="true"
        />
        <h2 className="mb-3 text-xl font-semibold text-white">
          {t("Marketplace.Releases.empty-title")}
        </h2>
        <p className="mx-auto mb-6 max-w-lg text-sm leading-relaxed text-grey">
          {t("Marketplace.Releases.empty-description")}
        </p>
        {onReset && (
          <button
            type="button"
            onClick={onReset}
            className="inline-flex min-h-11 items-center gap-2 rounded-xl border border-pink/30 bg-pink/10 px-4 py-2 text-sm text-[#ff91b7] hover:bg-pink hover:text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink"
          >
            <FiRotateCcw aria-hidden="true" />
            <span>{t("Marketplace.Releases.reset-filters")}</span>
          </button>
        )}
      </div>
    );
  }
  return (
    <section className="mt-8">
      <h2 className="mb-4 text-xl font-semibold tracking-tight text-white">
        {t("Marketplace.Releases.result-count", { count: releases.length })}
      </h2>
      <div className="grid gap-4 lg:grid-cols-2">
        {releases.map((release, index) => {
          const binary = release.binary;
          const titleId = `${id}-${index}`;
          const vendorName =
            vendors.find(
              (vendor) => getVendorIdentifier(vendor) === release.vendor,
            )?.name ?? capitalize(release.vendor);
          const os =
            binary.os === "mac"
              ? "macOS"
              : binary.os === "alpine_linux"
                ? "Alpine Linux"
                : capitalize(binary.os);
          const architecture =
            binary.os === "mac"
              ? binary.architecture === "aarch64"
                ? "Apple Silicon"
                : binary.architecture === "x64"
                  ? "Intel (x64)"
                  : binary.architecture
              : binary.architecture;
          const metadata = [
            {
              key: "date",
              label: t("Marketplace.Releases.build-date"),
              value: new Date(binary.timestamp).toLocaleDateString(locale, {
                day: "2-digit",
                month: "2-digit",
                year: "numeric",
              }),
            },
            {
              key: "os",
              label: t("Temurin.Releases.ReleaseFilters.operating-system"),
              value: os,
            },
            {
              key: "arch",
              label: t("Temurin.Releases.ReleaseFilters.architecture"),
              value: architecture,
            },
            {
              key: "vendor",
              label: t("Marketplace.Releases.vendor"),
              value: vendorName,
            },
          ];
          return (
            <article
              key={`${release.vendor}-${release.release_name}-${binary.package.link}`}
              aria-labelledby={titleId}
              data-testid="marketplace-release"
              className="flex min-w-0 flex-col rounded-2xl border border-white/10 bg-white/[0.025] p-5 text-white sm:p-6"
            >
              <div className="flex items-start justify-between gap-3">
                <div className="flex min-w-0 items-center gap-3">
                  <div className="flex h-12 w-16 shrink-0 items-center justify-center rounded-xl bg-white p-2">
                    <Image
                      src={getImageForDistribution(binary.distribution)}
                      alt={`${binary.distribution} logo`}
                      width={48}
                      height={32}
                      className="h-8 w-12 object-contain"
                    />
                  </div>
                  <div className="min-w-0">
                    <p className="mb-1 text-xs text-grey">
                      {capitalize(binary.distribution)}
                    </p>
                    <h3
                      id={titleId}
                      className="mb-0 break-words text-lg font-semibold leading-snug tracking-tight"
                    >
                      {release.release_name}
                    </h3>
                  </div>
                </div>
                <span className="shrink-0 rounded-full border border-white/10 px-2.5 py-1 font-mono text-xs text-grey">
                  {binary.image_type.toUpperCase()}
                </span>
              </div>
              <dl className="my-5 grid grid-cols-2 gap-4 border-y border-white/10 py-4 sm:grid-cols-4">
                {metadata.map((item) => (
                  <div key={item.key}>
                    <dt className="mb-1 text-xs text-grey">{item.label}</dt>
                    <dd className="m-0 break-words text-sm font-medium">
                      {item.value}
                    </dd>
                  </div>
                ))}
              </dl>
              <div className="mt-auto flex flex-wrap items-center justify-between gap-3">
                <button
                  type="button"
                  disabled={!binary.package.sha256sum}
                  aria-label={t("Marketplace.Releases.view-checksum")}
                  onClick={() => {
                    setCurrentChecksum(binary.package.sha256sum);
                    setModalOpen(true);
                  }}
                  className="inline-flex min-h-11 items-center gap-2 rounded-lg px-2 text-xs text-grey hover:text-white focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink disabled:cursor-not-allowed disabled:opacity-40"
                >
                  <BsCopy aria-hidden="true" />
                  <span>{t("Temurin.Releases.ReleaseResults.checksum")}</span>
                </button>
                <Link
                  href={{
                    pathname: "/download",
                    query: {
                      link: binary.package.link,
                      vendor: capitalize(release.vendor),
                    },
                  }}
                  onClick={() =>
                    sendDownloadEvent({
                      link: binary.package.link,
                      os: binary.os,
                      arch: binary.architecture,
                      pkg_type: binary.image_type,
                      version: release.release_name,
                      vendor: capitalize(release.vendor),
                    })
                  }
                  className="inline-flex min-h-11 items-center gap-2 rounded-xl bg-pink px-4 py-2 text-sm font-semibold text-white transition-colors hover:bg-[#df0b54] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-white"
                >
                  <FiDownload aria-hidden="true" />
                  <span>{`${t("Marketplace.Releases.download")} (${getExtension(binary.package.name).toUpperCase()})`}</span>
                </Link>
              </div>
            </article>
          );
        })}
      </div>
      <ChecksumModal
        open={modalOpen}
        setOpen={setModalOpen}
        checksum={currentChecksum}
      />
    </section>
  );
};
export default AllReleaseCard;
